def cache_sim(capacity, ttl, ops):
    from collections import OrderedDict

    cache = OrderedDict()  # {key: (value, write_time)}
    results = []
    current_time = 0

    for op in ops:
        op_type = op[0]
        t = op[1]
        current_time = t

        # Remove expired entries
        expired_keys = []
        for key, (value, write_time) in cache.items():
            if current_time >= write_time + ttl:
                expired_keys.append(key)
        for key in expired_keys:
            del cache[key]

        if op_type == 'put':
            key = op[2]
            value = op[3]

            # If key already exists, remove it first
            if key in cache:
                del cache[key]
            # If cache is at capacity, evict LRU (first item)
            elif len(cache) >= capacity:
                cache.popitem(last=False)

            # Add the new entry (most recently used)
            cache[key] = (value, t)

        elif op_type == 'get':
            key = op[2]

            if key in cache:
                value, write_time = cache[key]
                # Move to end (most recently used)
                del cache[key]
                cache[key] = (value, write_time)
                results.append(value)
            else:
                results.append(-1)

    return results

